/// Canonical spelling of a G word: uppercase, and numbered codes lose
/// their leading zeros (g001 -> G1, manual 3.2.2.1). Keywords only change case.
pub fn normalize_g_command(word: &str) -> String {
    let mut code = word.to_ascii_uppercase();
    if let Some(digits) = code.strip_prefix('G') {
        if !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit()) {
            let zeros = digits.bytes().take_while(|&b| b == b'0').count();
            let remove = zeros.min(digits.len() - 1);
            code.drain(1..1 + remove);
        }
    }
    code
}

